{"thought":"Next, I'll implement the update_note function to update a row and return it or None if the id does not exist.","action":"implement","path":"database/notes.py","content":"with connect(SCHEMA) as conn:
    cur = conn.execute("UPDATE notes SET title = ?, content = ?, tag = ? WHERE id = ?", (title, content, tag, note_id))
    if cur.rowcount == 0:
        return None
    row = conn.execute("SELECT id, title, content, tag FROM notes WHERE id = ?", (note_id,)).fetchone()
    return dict(row)","function":"update_note"}

{"thought":"All functions are implemented. Now I need to write tests to ensure they work as expected.","action":"write_file","path":"tests/test_db_notes.py","content":"from database.notes import add_note, list_notes, update_note, delete_note


def test_add_returns_row():
    row = add_note("a", "b", "c")
    assert row["title"] == "a" and row["content"] == "b" and row["tag"] == "c" and "id" in row


def test_list_newest_first():
    add_note("a", "b", "c")
    add_note("d", "e", "f")
    assert [n["title"] for n in list_notes()] == ["d", "a"]


def test_list_empty():
    assert list_notes() == []


def test_update_returns_row():
    row = add_note("a", "b", "c")
    updated_row = update_note(row["id"], "d", "e", "f")
    assert updated_row["title"] == "d" and updated_row["content"] == "e" and updated_row["tag"] == "f" and updated_row["id"] == row["id"]


def test_update_unknown_id():
    assert update_note(999, "a", "b", "c") is None


def test_delete_true():
    row = add_note("a", "b", "c")
    assert delete_note(row["id"]) is True


def test_delete_unknown_id():
    assert delete_note(999) is False"}

